      - If (skip_array[i] == 1) continue;
      - If (write_mask_array[i] == 0x00000000) continue;
      - write_reg(addr, (data_wr & write_mask_array[i]));
    - Read/verify phase (i = 0..CNT-1):
      - addr = addr_array[i];
      - If (skip_array[i] == 1) continue;
      - If (write_mask_array[i] == 0x00000000) continue;
